package com.cricketprediction.backend.dto.toss;

/**
 * Recommendations generated by the Toss Decision Advisor.
 */
public enum TossRecommendation {
    BAT_FIRST("Bat First"),
    FIELD_FIRST("Field First (Bowl First)"),
    NO_CLEAR_ADVANTAGE("No Clear Advantage"),
    INSUFFICIENT_DATA("Insufficient Historical Data");

    private final String label;

    TossRecommendation(String label) {
        this.label = label;
    }

    public String getLabel() {
        return label;
    }
}
